-- راهنمای کامل پنل مدیریت برای دستیار پنل (admin scope)
-- تولیدشده از supabase/seed/admin_assistant_knowledge.json — فقط افزودن/به‌روزرسانی ردیف‌های راهنما، بدون حذف هیچ داده‌ای.

on conflict (lower(question)) do update set
  answer = excluded.answer,
  aliases = excluded.aliases,
  keywords = excluded.keywords,
  target_tab = excluded.target_tab,
  target_focus = excluded.target_focus,
  action_label = excluded.action_label,
  response_mode = excluded.response_mode,
  match_mode = excluded.match_mode,
  status = excluded.status,
  is_active = excluded.is_active,
  priority = excluded.priority,
  updated_at = now();
