insert into public.assistant_admin_knowledge
  (question,answer,aliases,keywords,category,target_tab,target_focus,action_label,response_mode,match_mode,status,is_active,priority,created_by)
values
  ('هر تغییری را چطور ذخیره کنم؟','در پنل مدیریت هر بخش دکمه ذخیره خودش را دارد؛ زیر همان فهرست یا فرم، دکمه‌ای با نام بخش (مثلاً «ذخیره تنظیمات دیزاین» یا «ذخیره جملات اعتمادساز») را بزنید. بعد از زدن، پیام «ذخیره‌سازی کامل شد» نمایش داده می‌شود و تغییر روی سایت اعمال می‌گردد.',array['تغییری ذخیره','ذخیره','ذخیره کردن','ذخیره تغییرات','ثبت تغییرات','داشبورد']::text[],array['ذخیره','پیام ذخیره']::text[],'راهنمای پنل','dashboard','','رفتن به داشبورد','exact','contains','published',true,8,'panel-guide-seed'),
  ('تغییرات من ذخیره شد یا نه؟','هر بار که دکمه ذخیره یک بخش را می‌زنید، پنل پیام «ذخیره‌سازی کامل شد» را نشان می‌دهد. اگر پیام خطا دیدید، تغییر ذخیره نشده و باید دوباره تلاش کنید. برای اطمینان، صفحه سایت را تازه‌سازی (Refresh) کنید.',array['تغییرات ذخیره','داشبورد']::text[],'{}','راهنمای پنل','dashboard','','رفتن به این کنترل','exact','contains','published',true,8,'panel-guide-seed'),
  ('یک مشتری را با نام یا شماره پیدا کن','در پنل کافی است در کادر سؤال دستیار بنویسید «فلان نام» یا بخشی از شماره تماس؛ دستیار درون دیتابیس پروژه جست‌وجو می‌کند (بدون ارسال اطلاعات به بیرون) و نتیجه را با نام، وضعیت و دکمه «بازکردن پرونده در پنل» نشان می‌دهد.',array['مشتری نام شماره','جستجوی مشتری','پیدا کردن کاربر','شماره تماس کاربر','فرم‌ها']::text[],array['مشتری']::text[],'راهنمای پنل','data','فرم‌ها و سفارشات','رفتن به فرم‌ها و سفارشات','exact','contains','published',true,8,'panel-guide-seed'),
  ('سایت را کجا ببینم؟','در بالای پنل، دکمه «بازدید از سایت» شما را به صفحه اصلی سایت می‌برد. برای دیدن نتیجه تغییرات، بعد از ذخیره این دکمه را بزنید.',array['سایت ببینم','داشبورد']::text[],'{}','راهنمای پنل','dashboard','پایش هوشمند ظرفیت دیتابیس','رفتن به این کنترل','exact','contains','published',true,8,'panel-guide-seed'),
  ('داشبورد پنل چه اطلاعاتی می‌دهد؟','داشبورد نمای کلی امروز است: تعداد فرم‌ها و سفارش‌های «در انتظار بررسی»، «فعالیت اخیر» مدیران و کارت پایش فضای دیتابیس و تصاویر. از همین‌جا می‌توانید بک‌آپ اکسلی یا بک‌آپ کامل بگیرید.',array['داشبورد پنل اطلاعاتی','داشبورد','خوش آمدید','نمای کلی']::text[],array['داشبورد','اماری']::text[],'راهنمای پنل','dashboard','در انتظار بررسی','رفتن به داشبورد','exact','contains','published',true,8,'panel-guide-seed'),
  ('ظرفیت دیتابیس و فضای عکس‌ها را چطور بفهمم؟','در داشبورد، کارت «پایش هوشمند ظرفیت دیتابیس و فضای ذخیره‌سازی» درصد فضای آزاد را نشان می‌دهد. اگر به زیر ۱۰٪ رسید، از همان‌جا «بک‌آپ کامل (ZIP)» بگیرید و تصویرهای اضافه را پاک کنید.',array['ظرفیت دیتابیس فضای','فضای سایت','حافظه','استوریج','ظرفیت','داشبورد']::text[],array['فضا','بک‌آپ']::text[],'راهنمای پنل','dashboard','پایش هوشمند ظرفیت دیتابیس','رفتن به پایش فضا','exact','contains','published',true,8,'panel-guide-seed'),
  ('بک‌آپ گرفتن از اطلاعات سایت','در داشبورد دو دکمه هست: «بک‌آپ Excel» برای جدول فرم‌ها و سفارش‌ها، و «بک‌آپ کامل (ZIP)» برای همه اطلاعات و فایل‌ها. ماهی یک‌بار بک‌آپ کامل توصیه می‌شود.',array['بک‌آپ گرفتن اطلاعات','بکاپ','پشتیبان','اکسل گرفتن','خروجی اکسل','داشبورد']::text[],array['بک‌آپ','اکسل']::text[],'راهنمای پنل','dashboard','پایش هوشمند ظرفیت دیتابیس','رفتن به بخش بک‌آپ','exact','contains','published',true,8,'panel-guide-seed'),
  ('فعالیت اخیر مدیران را کجا ببینم؟','در داشبورد، قسمت «فعالیت اخیر» نشان می‌دهد کدام مدیر، چه تغییری، در چه ساعتی انجام داده است. برای فهرست کامل، همان‌جا «مشاهده همه» را بزنید.',array['فعالیت اخیر مدیران','لاگ مدیران','کی چه کاری کرد','تاریخچه تغییرات','داشبورد']::text[],array['فعالیت','مستندات']::text[],'راهنمای پنل','dashboard','فعالیت اخیر','رفتن به فعالیت اخیر','exact','contains','published',true,8,'panel-guide-seed'),
  ('فرم‌های پر شده کاربران کجا است؟','از منوی کناری «فرم‌ها و دوره‌ها» را باز کنید. در قسمت «فرم‌ها و سفارشات» فهرست همه ثبت‌نام‌ها با نام، شماره، وضعیت و کد پیگیری نمایش داده می‌شود. با جست‌وجو می‌توانید یک نفر را پیدا کنید.',array['فرم‌های شده کاربران','فرم‌ها','لیست فرم','سفارش‌ها','درخواست‌ها']::text[],array['فرم','سفارش']::text[],'راهنمای پنل','data','فرم‌ها و سفارشات','رفتن به فرم‌ها و سفارشات','exact','contains','published',true,8,'panel-guide-seed'),
  ('شماره یک مشتری را دادم، پرونده‌اش را پیدا کنم','در «فرم‌ها و دوره‌ها»، در کادر جست‌وجو بخشی از شماره یا نام را بنویسید؛ نتیجه فوراً فیلتر می‌شود. روی ردیف موردنظر کلیک کنید تا جزئیات و فیش‌ها باز شود.',array['شماره مشتری دادم،','جستجوی مشتری','پیدا کردن کاربر','شماره را بدهم','فرم‌ها']::text[],array['جست‌وجو','مشتری']::text[],'راهنمای پنل','data','فرم‌ها و سفارشات','رفتن به جست‌وجوی فرم‌ها','exact','contains','published',true,8,'panel-guide-seed'),
  ('کد پیگیری کاربر چیست و کجاست؟','به هر ثبت‌نام یک کد پیگیری کوتاه داده می‌شود که کاربر با همان وضعیتش را در صفحه «پیگیری دوره» می‌بیند. کد را در فهرست «فرم‌ها و سفارشات» ببینید و برای کاربر بفرستید.',array['پیگیری کاربر کجاست','کد رهگیری','کد پیگیری','کد سفارش','فرم‌ها']::text[],array['کد پیگیری']::text[],'راهنمای پنل','data','فرم‌ها و سفارشات','رفتن به فهرست فرم‌ها','exact','contains','published',true,8,'panel-guide-seed'),
  ('فیش واریزی کاربر را کجا ببینم؟','در همان ردیف «فرم‌ها و سفارشات»، پرونده کاربر را باز کنید؛ تصویر فیش واریزی و وضعیت پرداخت آنجا است. اگر تصویر را نمی‌بینید، در بخش «ارسال و پرداخت» گزینه «نمایش تصویر فیش واریزی» را روشن کنید.',array['فیش واریزی کاربر','فیش','رسید','عکس فیش','فرم‌ها']::text[],array['فیش واریزی']::text[],'راهنمای پنل','data','فرم‌ها و سفارشات','رفتن به فرم‌ها','exact','contains','published',true,8,'panel-guide-seed'),
  ('یک فرم را حذف کنم یا به حالت اول برگردانم','در «فرم‌ها و سفارشات» ردیف موردنظر را انتخاب (تیک «انتخاب همه» برای چندتا با هم) و عملیات حذف را بزنید؛ آیتم حذف‌شده به «سطل بازیافت» می‌رود و از همان‌جا قابل بازگردانی است.',array['فرم حذف حالت','حذف فرم','پاک کردن سفارش','بازگردانی','فرم‌ها']::text[],array['حذف','سطل']::text[],'راهنمای پنل','data','انتخاب همه','رفتن به انتخاب فرم‌ها','exact','contains','published',true,8,'panel-guide-seed'),
  ('سطل بازیافت و برگرداندن چیزهای حذف‌شده','از منوی کناری «سطل بازیافت» را باز کنید. هر چیزی که حذف شده (فرم، دوره، محصول، نظر) در «سطل آشغال» است و با دکمه بازگردانی به جای اولش برمی‌گردد.',array['سطل بازیافت برگرداندن','بازگردانی','حذف شده‌ها','سطل','سطل بازیافت']::text[],array['سطل بازیافت']::text[],'راهنمای پنل','trash','سطل آشغال','رفتن به سطل بازیافت','exact','contains','published',true,8,'panel-guide-seed'),
  ('سوالاتی که کاربران می‌فرستند کجا می‌آید؟','بخش «سوالات مخاطبین (سوال دارم)» همه پیام‌های فرم «سوال دارم» را با نام، شماره و متن نشان می‌دهد. می‌توانید وضعیت را تغییر دهید یا آن را به بخش «سوالات متداول (FAQ)» منتقل کنید.',array['سوالاتی کاربران می‌فرستند','سوال دارم','پیام کاربران','درخواست سوال','سوالات مخاطبین']::text[],array['سوالات']::text[],'راهنمای پنل','userQuestions','مدیریت سوالات و درخواست‌های مخاطبین','رفتن به سوالات مخاطبین','exact','contains','published',true,8,'panel-guide-seed'),
  ('سوالات متداول سایت را کجا ویرایش کنم؟','دو جا دارید: در «سوالات مخاطبین» قسمت «مدیریت سوالات متداول (FAQ)» و در «تنظیمات». پس از هر تغییر دکمه «ذخیره سوالات متداول» را بزنید.',array['سوالات متداول سایت','FAQ','سوال‌های پرتکرار','متداول','سوالات مخاطبین']::text[],array['سوالات متداول']::text[],'راهنمای پنل','userQuestions','مدیریت سوالات متداول','رفتن به سوالات متداول','exact','contains','published',true,8,'panel-guide-seed'),
  ('نظرات کاربران را کجا تأیید یا رد کنم؟','منوی «نظرات کاربران» → «مدیریت جامع نظرات، تجربیات و محل‌های نمایش». روی هر نظر می‌توانید وضعیت را به «تأیید شده» یا «در انتظار» ببرید و متن، نام و تاریخ را ویرایش کنید.',array['نظرات کاربران تأیید','تأیید نظر','نظر کاربر','تجربه والدین','کامنت','نظرات']::text[],array['نظرات']::text[],'راهنمای پنل','reviews','مدیریت جامع نظرات','رفتن به نظرات','exact','contains','published',true,8,'panel-guide-seed'),
  ('نظر یک کاربر در کدام قسمت‌های سایت نمایش داده شود؟','روی کارت هر نظر، بخش «محل‌های نمایش این نظر در سایت» و «دسترسی و محل‌های مجاز نمایش این نظر» را باز کنید و تیک جاهای دلخواه (هوم، دوره‌ها، …) را بزنید؛ سپس ذخیره کنید.',array['نظر کاربر کدام','نمایش نظر کجا باشد','محل نظر','نظرات']::text[],array['محل نمایش']::text[],'راهنمای پنل','reviews','مدیریت جامع نظرات','رفتن به مدیریت نظرات','exact','contains','published',true,8,'panel-guide-seed'),
  ('نام و شماره کسی که نظر داده را چطور عوض کنم؟','در «نظرات کاربران» روی «ویرایش» هر نظر بزنید و بخش «ویرایش نام، مقصد، شماره، تاریخ و متن نظر» را باز کنید؛ بعد از اصلاح، ذخیره را بزنید.',array['نام شماره کسی','ویرایش نظر','تغییر متن نظر','نظرات']::text[],array['ویرایش نظر']::text[],'راهنمای پنل','reviews','مدیریت جامع نظرات','رفتن به مدیریت نظرات','exact','contains','published',true,8,'panel-guide-seed'),
  ('مشاور اضافه کنم یا لینک ارجاع بسازم','منوی «مشاورین و لینک‌های ارجاع». با «افزودن» نام، شماره و لینک اختصاصی هر مشاور را وارد کنید؛ لینک ارجاع همان آدرسی است که برای آن مشاور می‌فرستید. در پایان ذخیره را بزنید.',array['مشاور اضافه لینک','اضافه کردن مشاور','لینک دعوت','کد معرفی','ارجاع','مشاورین']::text[],array['مشاور','ارجاع']::text[],'راهنمای پنل','consultants','مشاورین و لینک‌های ارجاع','رفتن به مشاورین','exact','contains','published',true,8,'panel-guide-seed'),
  ('متن پیام‌های پاپ‌آپ «درخواست مشاوره» را چطور عوض کنم؟','در «مشاورین و لینک‌های ارجاع» چند کادر متن وجود دارد: «متن پیام پاپ‌آپ «درخواست مشاوره مجدد»»، «عنوان دکمه اصلی پاپ‌آپ» و «سؤال «به چه دلیلی مجدداً درخواست مشاوره»». متن را عوض کنید و ذخیره را بزنید.',array['متن پیام‌های پاپ‌آپ','پاپ‌آپ','پیام درخواست مشاوره','مشاورین']::text[],array['پاپ‌آپ']::text[],'راهنمای پنل','consultants','متن پیام پاپ‌آپ','رفتن به متن‌های پاپ‌آپ','exact','contains','published',true,8,'panel-guide-seed'),
  ('دکمه‌های کناری صفحه اصلی (CTA) را کجا روشن/خاموش کنم؟','در همان بخش «مشاورین و لینک‌های ارجاع»، گزینه «نمایش دکمه‌های CTA صفحه اصلی» را تیک بزنید یا بردارید و ذخیره کنید.',array['دکمه‌های کناری صفحه','دکمه‌های هوم','CTA','مشاورین']::text[],array['دکمه‌ها']::text[],'راهنمای پنل','consultants','نمایش دکمه‌های CTA','رفتن به تنظیم CTA','exact','contains','published',true,8,'panel-guide-seed'),
  ('چطور یک دوره جدید اضافه کنم؟','منوی «دوره‌ها» → «مدیریت تب‌ها و دوره‌ها». تب مربوطه را باز کنید، «افزودن دوره» را بزنید، عنوان، توضیحات، قیمت و عکس را پر کنید و در پایان «ذخیره» را بزنید. برای ویرایش دوره موجود هم همین مسیر است.',array['دوره جدید اضافه','اضافه کردن دوره','دوره جدید','ویرایش دوره','ثبت دوره','دوره‌ها']::text[],array['دوره']::text[],'راهنمای پنل','courses','مدیریت تب‌ها و دوره‌ها','رفتن به مدیریت دوره‌ها','exact','contains','published',true,8,'panel-guide-seed'),
  ('قیمت یا تخفیف یک دوره را چطور عوض کنم؟','در «دوره‌ها» → «مدیریت تب‌ها و دوره‌ها»، دوره را باز کنید: «قیمت اصلی»، «قیمت تخفیف‌دار (اختیاری)» و «تاریخ پایان تخفیف (اختیاری)» را ویرایش کنید و «ذخیره» را بزنید.',array['قیمت تخفیف دوره','تغییر قیمت','تخفیف','قیمت دوره','دوره‌ها']::text[],array['قیمت','تخفیف']::text[],'راهنمای پنل','courses','قیمت تخفیف‌دار','رفتن به قیمت دوره','exact','contains','published',true,8,'panel-guide-seed'),
  ('عکس دوره را کجا آپلود کنم؟','در کارت هر دوره در «مدیریت تب‌ها و دوره‌ها» دکمه «آپلود عکس برای همین دوره» هست. اگر می‌خواهید عکس فقط برای یک تب باشد، «آپلود تصویر مخصوص همین تب» را بزنید؛ کادر و موقعیت برش را هم می‌توانید تنظیم کنید.',array['عکس دوره آپلود','تصویر دوره','عکس دوره','کاور دوره','دوره‌ها']::text[],array['عکس']::text[],'راهنمای پنل','courses','آپلود عکس برای همین دوره','رفتن به آپلود عکس دوره','exact','contains','published',true,8,'panel-guide-seed'),
  ('تب‌های دوره‌ها (رشد قد، بی‌اشتهایی، …) را چطور اضافه یا حذف کنم؟','در «دوره‌ها» → «مدیریت تب‌ها و دوره‌ها» می‌توانید تب جدید اضافه کنید، عنوان فارسی و انگلیسی، توضیح و «نمایش تصویر تب پیش از دوره‌ها» را تنظیم کنید و وضعیت «فعال» را روشن/خاموش کنید. در پایان «ذخیره» را بزنید.',array['تب‌های دوره‌ها (رشد','تب جدید','دسته دوره','حذف تب','دوره‌ها']::text[],array['تب‌ها']::text[],'راهنمای پنل','courses','مدیریت تب‌ها و دوره‌ها','رفتن به تب‌ها','exact','contains','published',true,8,'panel-guide-seed'),
  ('واحد پول سایت (تومان) را کجا عوض کنم؟','در بالای بخش «دوره‌ها» کارت «واحد پول دوره‌ها» هست. مقدار «واحد پول» را عوض کنید و ذخیره را بزنید تا در همه قیمت‌ها اعمال شود.',array['واحد پول سایت','تومان','واحد پول','پول دوره','دوره‌ها']::text[],array['واحد پول']::text[],'راهنمای پنل','courses','واحد پول دوره‌ها','رفتن به واحد پول','exact','contains','published',true,8,'panel-guide-seed'),
  ('متن «اطلاعات بیشتر» دوره را کجا بنویسم؟','در کارت هر دوره دو کادر دارید: «خلاصه اطلاعات بیشتر» و «متن کامل اطلاعات بیشتر». بعد از نوشتن، «ذخیره» را بزنید.',array['متن اطلاعات بیشتر','توضیحات دوره','اطلاعات بیشتر','دوره‌ها']::text[],array['توضیحات']::text[],'راهنمای پنل','courses','خلاصه اطلاعات بیشتر','رفتن به توضیحات دوره','exact','contains','published',true,8,'panel-guide-seed'),
