  ('موضوعات مشاوره و گزینه‌ها (گوارش، اشتها، شرایط خاص)','منوی «تنظیمات» و بخش‌های «موضوعات مشاوره»، «گزینه‌های گوارش»، «گزینه‌های اشتها»، «شرایط خاص» و «بازه‌های تماس». متن گزینه‌ها را اضافه/کم کنید و «دسته‌بندی‌ها» را تنظیم کنید؛ سپس ذخیره را بزنید.',array['موضوعات مشاوره گزینه‌ها','انتخاب موضوع','ساعت تماس','گزینه‌ها','تنظیمات']::text[],array['موضوعات']::text[],'راهنمای پنل','settings','موضوعات مشاوره','رفتن به موضوعات مشاوره','exact','contains','published',true,8,'panel-guide-seed'),
  ('متن «ثبت شد» و پیام‌های راهنما','منوی «تنظیمات» → «پیام‌های موفقیت و راهنما». کادرهای submitBtnText، successMsg، successSubMsg و timeSlotLabel را ویرایش کنید تا متن بعد از ثبت فرم همان چیزی باشد که می‌خواهید؛ سپس ذخیره کنید.',array['متن ثبت پیام‌های','پیام تشکر','متن موفقیت','submit','تنظیمات']::text[],array['پیام‌ها']::text[],'راهنمای پنل','settings','پیام‌های موفقیت و راهنما','رفتن به پیام‌های موفقیت','exact','contains','published',true,8,'panel-guide-seed'),
  ('رنگ و شکل سایت (دیزاین) را چطور عوض کنم؟','منوی «تنظیمات» → «مدیریت دیزاین». از کادر «دیزاین» یکی از چهار دیزاین (wellness، kidlearn، blend، classic) را انتخاب کنید و «ذخیره تنظیمات دیزاین» را بزنید. هر دیزاین پالت روشن و تاریک اختصاصی خودش را دارد.',array['رنگ شکل سایت','دیزاین','پوسته','رنگ سایت']::text[],array['دیزاین']::text[],'راهنمای پنل','design','مدیریت دیزاین','رفتن به مدیریت دیزاین','exact','contains','published',true,8,'panel-guide-seed'),
