  ('صفحه اول سایت «پیگیری» باشد یا «پنل کاربر»؟','منوی «تنظیمات» → «صفحه ورودی سایت». حالت را انتخاب کنید و با دکمه «ذخیره و فعال‌سازی» همان‌جا اعمالش کنید. در حالت پنل کاربر، ورود/ثبت‌نام با پیامک است و در حالت پیگیری فقط کد پیگیری.',array['صفحه اول سایت','حالت ورودی','پنل کاربر','پیگیری دوره','صفحه ورودی']::text[],array['ورودی']::text[],'راهنمای پنل','entry','پنل پیامکی','رفتن به صفحه ورودی','exact','contains','published',true,8,'panel-guide-seed'),
  ('تنظیمات پیامک ثبت‌نام (کاونگار)','منوی «تنظیمات» → «صفحه ورودی سایت». «پنل پیامکی» را روی حالت تست یا واقعی بگذارید، «شماره خط ارسال» و «کلید API» را وارد کنید و ذخیره کنید. کلید فقط در تنظیمات می‌ماند و به دست عموم نمی‌رسد.',array['تنظیمات پیامک ثبت‌نام','کاونگار','پیامک','رمز یکبارمصرف','otp','صفحه ورودی']::text[],array['پیامک']::text[],'راهنمای پنل','entry','پنل پیامکی','رفتن به پنل پیامکی','exact','contains','published',true,8,'panel-guide-seed'),
  ('کپچای ثبت‌نام (Cloudflare Turnstile) را روشن کنم','منوی «تنظیمات» → «صفحه ورودی سایت» → «فعالسازی Cloudflare Turnstile در فرم ثبت‌نام» را روشن کنید، کلیدهای Turnstile را وارد و «ذخیره و فعال‌سازی» را بزنید.',array['کپچای ثبت‌نام (Cloudflare','کپچا','turnstile','ضد ربات','صفحه ورودی']::text[],array['کپچا']::text[],'راهنمای پنل','entry','فعالسازی Cloudflare Turnstile','رفتن به کپچا','exact','contains','published',true,8,'panel-guide-seed'),
