  ('به دستیار سایت چیزی یاد بدهم','منوی «دستیار» → «آموزش دانش جدید». سؤال، پاسخ، «کلیدواژه‌ها» و «میان‌برها (aliases)» را بنویسید، وضعیت را روی «منتشر» بگذارید و «ذخیره دانش» را بزنید. اگر می‌خواهید پاسخ به یک بخش پنل وصل شود، از همان‌جا تب و عنوان کنترل را انتخاب کنید تا کاربر با دکمه «رفتن به بخش مرتبط» مستقیم برود.',array['دستیار سایت یاد','یاد دادن','افزودن پاسخ','دانش جدید','آموزش دستیار','دستیار']::text[],array['دانش']::text[],'راهنمای پنل','assistant','آموزش دانش جدید','رفتن به آموزش دانش','exact','contains','published',true,8,'panel-guide-seed'),
  ('سؤالاتی که دستیار جوابش را نمی‌داند','منوی «دستیار» → «سؤال‌های بی‌پاسخ کاربران». هر سؤالی که بی‌جواب مانده اینجا است؛ روی آن بزنید، پاسخ بنویسید و ذخیره کنید تا دفعه بعد جواب بدهد.',array['سؤالاتی دستیار جوابش','بی پاسخ','سوال بدون جواب','دستیار']::text[],array['بی‌پاسخ']::text[],'راهنمای پنل','assistant','سؤال‌های بی‌پاسخ کاربران','رفتن به سؤال‌های بی‌پاسخ','exact','contains','published',true,8,'panel-guide-seed'),
  ('جواب دستیار را قبل از انتشار آزمایش کنم','منوی «دستیار» → «آزمایش قبل از استفاده». سؤال را بنویسید و «آزمایش» را بزنید تا ببینید دستیار کدام دانش را انتخاب می‌کند و چه پاسخی می‌دهد. می‌توانید «هر دو» (عمومی و مدیریتی) را یکجا تست کنید.',array['جواب دستیار قبل','تست دستیار','آزمایش پاسخ','دستیار']::text[],array['آزمایش']::text[],'راهنمای پنل','assistant','آزمایش قبل از استفاده','رفتن به آزمایش','exact','contains','published',true,8,'panel-guide-seed'),
