  ('بک‌آپ یا بازیابی دانش دستیار','منوی «دستیار» → «بکاپ کامل دانش» فایل مارک‌داون همه سؤال‌ها و پاسخ‌ها را می‌گیرد. برای برگرداندن یا افزودن دسته‌ای، همان‌جا «وارد کردن دسته‌جمعی» وجود دارد (هر سطر: سؤال | پاسخ).',array['بک‌آپ بازیابی دانش','خروجی دانش','بازگردانی دانش','امپورت','دستیار']::text[],array['بکاپ']::text[],'راهنمای پنل','assistant','بکاپ کامل دانش','رفتن به بکاپ دانش','exact','contains','published',true,8,'panel-guide-seed'),
  ('یک جمله بنویسم و دستیار خودش دانش بسازد','منوی «دستیار» → «آموزش با یک جمله». جمله ساده بنویسید (مثلاً: از این به بعد اگر کسی قیمت دوره پرسید بگو ۱/۲ میلیون تومان). پیش‌نویس ساخته می‌شود؛ شما بررسی و «ذخیره» می‌کنید — بدون تأیید شما چیزی ذخیره نمی‌شود.',array['جمله بنویسم دستیار','دستور متنی','یک جمله','تمرین دستیار','دستیار']::text[],array['آموزش سریع']::text[],'راهنمای پنل','assistant','آموزش با یک جمله','رفتن به آموزش با یک جمله','exact','contains','published',true,8,'panel-guide-seed'),
  ('فهرست همه چیزهایی که دستیار بلد است','منوی «دستیار» → «فهرست». سؤال‌ها و پاسخ‌های عمومی و مدیریتی را جدا یا با هم نشان می‌دهد؛ هر مورد را می‌توانید ویرایش، غیرفعال یا حذف کنید. وضعیت «منتشر/پیش‌نویس» مشخص می‌کند کدام‌ها فعال است.',array['فهرست همه چیزهایی','دانش‌های دستیار','لیست سوالات دستیار','دستیار']::text[],array['فهرست دانش']::text[],'راهنمای پنل','assistant','فهرست','رفتن به فهرست دانش','exact','contains','published',true,8,'panel-guide-seed'),
  ('دستیار پنل مدیریت چیست؟','یک راهنمای کوچک گوشه پنل است: هر سؤالی درباره تنظیمات، فرم‌ها، دوره‌ها یا پیدا کردن مشتری بنویسید؛ پاسخ آماده + دکمه‌ای می‌گیرید که شما را به همان کنترل می‌برد. جست‌وجوی مشتری داخل دیتابیس خودتان انجام می‌شود و اطلاعات به بیرون فرستاده نمی‌شود.',array['دستیار پنل مدیریت','راهنمای پنل','دستیار پنل','کمک پنل','دستیار']::text[],array['دستیار']::text[],'راهنمای پنل','assistant','','رفتن به دستیار','exact','contains','published',true,8,'panel-guide-seed')
